// CD Commission — Customer-Facing PDF Render Layer
// Scoped data for the paged-PDF prototype.
// Vendor identity LOCKED per brief §4. Customer + SKU + tier values
// carried from the Quote-Workflow A.1-v2 customer artifact (DPS-2418).
// Every field below is customer-visible. No forbidden field (margin, markup,
// cost, supplier, duty/tariff, CBM, version, scenario, audit) appears here —
// the boundary guard (brief §1) is enforced at the data layer too.
// Annotated in docs/cd-customer-pdf-render-data-source-map.md

window.NXCPDF = (function () {

  // ─── Vendor (LOCKED — brief §4) ─────────────────────────
  const vendor = {
    name: "The DPS",
    sub: "Turnkey product development & manufacturing for beauty, health & wellness brands",
    address: "3943 Irvine Blvd, #1129 · Irvine, CA 92602",
    contact_name: "Maya Okafor",
    contact_email: "maya@dps.co",
    contact_phone: "+1 (909) 555-0142",
  };

  // ─── Customer (from HubSpot projection) ─────────────────
  const customer = {
    name: "Lumen & Co.",
    contact: "Beth Yamamoto",
    role: "VP Operations",
    email: "beth@lumenco.com",
    address: "1450 Mission St · San Francisco, CA 94103",
  };

  // ─── Quote meta (customer-facing fields only) ───────────
  const quote = {
    quote_number: "DPS-2418",          // friendly id — never version/scenario
    issued_date: "2026-05-17",
    valid_until: "2026-08-31",
    payment_terms: "50% deposit on PO · balance Net 30 from ship date",
    lead_time: "10–12 weeks from PO approval; first shipment FOB Long Beach",
    incoterms_bundled: "FOB Long Beach — container freight, duty & applicable tariffs included in unit price",
    incoterms_passthrough: "EXW Long Beach — outbound freight billed separately at cost; charges itemized",
    customer_facing_notes:
      "Pricing assumes a single port-of-origin (Ningbo). Bulk-material costs are subject to a ±2% adjustment if published indices move more than 15% before PO. Tooling is shown as a one-time charge and amortizes into unit cost from Tier 3 forward.",
  };

  // ─── Tiers (up to 4; one recommended) ───────────────────
  const tiers = [
    { id: "t1", label: "T1", full: "Tier 1", quantity: 5000  },
    { id: "t2", label: "T2", full: "Tier 2", quantity: 10000, recommended: true },
    { id: "t3", label: "T3", full: "Tier 3", quantity: 25000 },
    { id: "t4", label: "T4", full: "Tier 4", quantity: 50000 },
  ];
  const recommendedTierIdx = 1; // T2

  // ─── SKUs (customer-visible subset) ─────────────────────
  // shape: "step" | "flat" | "partial"   (drives render treatment, not a forbidden field)
  // tier_prices: [t1, t2, t3, t4] — NULL → "quote on request", never $0.00
  const skus = [
    {
      id: "s1", code: "GLW-30", name: "Hydra-Glow Vitamin C Serum",
      pack: "30 ml glass dropper, screw cap", retail_benchmark: 48,
      tier_prices: [4.45, 3.95, 3.49, 3.18], shape: "step",
    },
    {
      id: "s2", code: "GLW-50", name: "Hydra-Glow Vitamin C Serum",
      pack: "50 ml glass dropper, screw cap", retail_benchmark: 68,
      tier_prices: [6.85, 6.10, 5.42, 4.92], shape: "step",
    },
    {
      id: "s3", code: "RPL-200", name: "Replenish Body Lotion",
      pack: "200 ml HDPE pump bottle", retail_benchmark: 32,
      tier_prices: [4.65, 4.65, 4.65, 4.65], shape: "flat",
    },
    {
      id: "s4", code: "RPL-400", name: "Replenish Body Lotion",
      pack: "400 ml HDPE pump bottle", retail_benchmark: 48,
      tier_prices: [7.85, 7.20, 6.55, 5.95], shape: "step",
    },
    {
      id: "s5", code: "CAP-60", name: "Glow Capsule — Daily Inner Beauty",
      pack: "60 ct PET bottle, child-resistant cap", retail_benchmark: 38,
      tier_prices: [null, 7.55, 6.70, 6.05], shape: "partial",
    },
    {
      id: "s6", code: "SRM-15", name: "Overnight Repair Serum",
      pack: "15 ml airless pump", retail_benchmark: 72,
      tier_prices: [9.20, 8.45, 7.60, 6.95], shape: "step",
    },
  ];

  // SKU subsets per state (prototype navigation; production renders the quote's actual set)
  const skuSets = {
    pure:        ["s1", "s2", "s3", "s4"],            // 4 priced (incl. one flat)
    passThrough: ["s1", "s2", "s3", "s4"],            // same set + charges block → 2 pages
    partial:     ["s1", "s2", "s3", "s4", "s5", "s6"],// 6 SKUs, one unpriced tier → table overflows
  };

  // ─── One-time charges (state B — allocate_service_fees_to_cost = FALSE) ──
  const service_fees = [
    {
      id: "sf1", scope: "project",
      label: "Project setup & tooling",
      sub: "Per-project, one-time. Includes filling-line setup, dye-cuts, plates.",
      amount: 4800, qty_label: "1 (per project)",
    },
    {
      id: "sf2", scope: "sku", sku_id: "s2",
      label: "GLW-50 — custom mold tooling",
      sub: "One-time. Mold ownership transfers to client at PO + 50k cumulative units.",
      amount: 9600, qty_label: "1 (GLW-50 only)",
    },
  ];

  // ─── Pass-through freight lines (state B — freight_treatment = pass_through) ──
  // Customer sees a landed per-unit amount per line; per-tier amounts on request.
  const freight_lines = [
    {
      id: "fr1", label: "Inbound ocean — Ningbo → Long Beach",
      sub: "Container freight allocated per unit. Booked & billed at cost as LCL/FCL is confirmed.",
      qty_label: "Per unit · per shipment",
      tier_amounts: [0.48, 0.42, 0.36, 0.31],
    },
    {
      id: "fr2", label: "Outbound LTL — Long Beach → Lumen DC (Tracy, CA)",
      sub: "Per shipment. Estimate at current rates; actual billed at cost + 15%.",
      qty_label: "Per unit · per shipment",
      tier_amounts: [0.38, 0.31, 0.26, 0.22],
    },
  ];

  return {
    vendor, customer, quote, tiers, recommendedTierIdx,
    skus, skuSets, service_fees, freight_lines,
  };
})();

/* CD Commission — Customer-Facing PDF Render Layer
   ───────────────────────────────────────────────────────────────────────────
   The paged layer. Authored within paged-PDF primitives (brief §3):
     · flexbox composition only — NO css grid, NO css `gap` inside the sheet
       (spacing is margin-based so it ports to react-pdf StyleSheet 1:1)
     · explicit US-Letter page boxes (8.5in × 11in @ 96dpi = 816 × 1056px)
     · running header/footer modelled as position:absolute within the page
       (= react-pdf `fixed`); page-break behaviour modelled by hard-split pages
   Names here (.pp-*) are the canonical structure CC implements verbatim (Pattern 30).
   Everything .pp-* is fixed-light: the PDF is print-target, theme-independent.
   The surrounding .cpdf-* chrome is preview-only and is NOT part of the artifact.
   ─────────────────────────────────────────────────────────────────────────── */

/* ─── Preview stage (NOT in the PDF) ──────────────────────── */
.cpdf-stage {
  background:
    repeating-linear-gradient(45deg,
      oklch(from var(--paper) calc(l - 0.02) c h) 0 12px,
      var(--paper) 12px 24px);
  min-height: 100vh;
  padding: 28px 40px 96px;
}
.cpdf-toolbar {
  max-width: 816px;
  margin: 0 auto 16px;
  display: flex; align-items: center; justify-content: space-between;
  gap: 16px;
  padding: 10px 14px;
  background: var(--paper-2);
  border: 1px solid var(--rule);
  border-radius: 8px;
  flex-wrap: wrap;
}
.cpdf-toolbar .grp { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.cpdf-toolbar .ribbon {
  font-family: var(--mono);
  font-size: 9.5px; letter-spacing: 0.10em; text-transform: uppercase;
  color: var(--internal);
  background: var(--internal-soft);
  border: 1px solid oklch(from var(--internal) l c h / 0.35);
  padding: 4px 8px; border-radius: 4px;
}
.cpdf-toolbar .seg {
  display: flex; background: var(--paper); border: 1px solid var(--rule);
  border-radius: 7px; padding: 2px;
}
.cpdf-toolbar .seg button {
  background: transparent; border: none; padding: 6px 11px; border-radius: 5px;
  font-family: var(--mono); font-size: 10px; letter-spacing: 0.05em; text-transform: uppercase;
  color: var(--ink-3); cursor: pointer; white-space: nowrap;
}
.cpdf-toolbar .seg button.active { background: var(--paper-3); color: var(--ink); box-shadow: 0 1px 2px rgba(0,0,0,0.07); }
.cpdf-toolbar .layout-toggle {
  display: flex; align-items: center; gap: 4px;
  font-family: var(--mono); font-size: 10.5px; color: var(--ink-3); letter-spacing: 0.02em;
}
.cpdf-toolbar .layout-toggle button {
  background: transparent; border: none; padding: 3px 7px; cursor: pointer;
  font-family: inherit; font-size: inherit; color: var(--ink-4);
}
.cpdf-toolbar .layout-toggle button.active { color: var(--ink); text-decoration: underline; text-underline-offset: 3px; }
.cpdf-toolbar .layout-toggle .bar { color: var(--ink-4); }
.cpdf-dl { display: flex; align-items: center; gap: 8px; }

.cpdf-dn {
  max-width: 816px; margin: 0 auto 16px;
  background: oklch(0.96 0.04 88);
  border-left: 3px solid oklch(0.65 0.16 75);
  padding: 11px 16px; border-radius: 4px;
  font-size: 12px; line-height: 1.55; color: oklch(0.30 0.05 80);
}
[data-theme="dark"] .cpdf-dn { background: oklch(0.22 0.05 80); color: oklch(0.85 0.04 85); }
.cpdf-dn .eyebrow {
  font-family: var(--mono); font-size: 9.5px; text-transform: uppercase;
  letter-spacing: 0.10em; color: oklch(0.45 0.10 75); margin-bottom: 4px;
}
[data-theme="dark"] .cpdf-dn .eyebrow { color: oklch(0.75 0.12 75); }
.cpdf-dn code {
  font-family: var(--mono); font-size: 11px;
  background: oklch(0.92 0.03 85); padding: 0 4px; border-radius: 3px;
}
[data-theme="dark"] .cpdf-dn code { background: oklch(0.30 0.04 80); }
.cpdf-dn strong { color: oklch(0.20 0.05 80); }
[data-theme="dark"] .cpdf-dn strong { color: oklch(0.95 0.02 85); }

/* Page-break marker between sheets (preview-only annotation) */
.cpdf-break {
  max-width: 816px; margin: 14px auto;
  display: flex; align-items: center; gap: 12px;
  font-family: var(--mono); font-size: 9px; letter-spacing: 0.12em; text-transform: uppercase;
  color: var(--ink-4);
}
.cpdf-break::before, .cpdf-break::after { content: ""; flex: 1; border-top: 1px dashed var(--rule-2); }

/* ════════════════════════════════════════════════════════════
   THE PAGED ARTIFACT  ·  everything below = react-pdf-portable
   ════════════════════════════════════════════════════════════ */

/* US Letter page box. Print-fixed palette (local, theme-independent). */
.pp-sheet {
  --pp-ink:      oklch(0.21 0.018 255);
  --pp-ink-2:    oklch(0.36 0.016 255);
  --pp-ink-3:    oklch(0.52 0.014 255);
  --pp-muted:    oklch(0.60 0.012 255);
  --pp-rule:     oklch(0.86 0.010 90);
  --pp-rule-2:   oklch(0.74 0.012 90);
  --pp-strong:   oklch(0.21 0.018 255);
  --pp-rec-edge: oklch(0.46 0.03 255);
  --pp-rec-tint: oklch(0.975 0.020 95);
  --pp-star:     oklch(0.56 0.13 72);
  --pp-paper:    oklch(0.995 0.002 95);

  position: relative;
  width: 816px;
  min-height: 1056px;
  margin: 0 auto;
  background: var(--pp-paper);
  color: var(--pp-ink);
  font-family: "Newsreader", Georgia, serif;
  padding: 56px 64px 88px;            /* bottom pad reserves the fixed footer band */
  box-sizing: border-box;
  display: flex; flex-direction: column;
  box-shadow:
    0 1px 0 oklch(0 0 0 / 0.18),
    0 24px 50px oklch(0 0 0 / 0.30),
    0 60px 110px oklch(0 0 0 / 0.16);
}
.pp-sheet + .pp-sheet { margin-top: 0; }
.pp-sheet * { box-sizing: border-box; }
.pp-flow { flex: 1 0 auto; }          /* flowing content; footer pinned below */

/* ─── Masthead (first page only) ──────────────────────────── */
.pp-masthead {
  display: flex; align-items: flex-start; justify-content: space-between;
  padding-bottom: 16px;
  border-bottom: 1.5px solid var(--pp-strong);
}
.pp-masthead .v-name {
  font-family: "Newsreader", Georgia, serif;
  font-size: 27px; font-weight: 500; letter-spacing: -0.02em;
  color: var(--pp-ink); line-height: 1.05;
}
.pp-masthead .v-sub {
  font-size: 12px; color: var(--pp-ink-3); margin-top: 5px; max-width: 42ch; line-height: 1.45;
}
.pp-masthead .v-meta {
  text-align: right; flex-shrink: 0; margin-left: 28px;
  font-family: "JetBrains Mono", ui-monospace, monospace;
  font-size: 10px; color: var(--pp-ink-3); letter-spacing: 0.03em; line-height: 1.85;
}
.pp-masthead .v-meta .qnum {
  display: block; font-size: 16px; color: var(--pp-ink); letter-spacing: 0.02em; margin-bottom: 6px;
}
.pp-masthead .v-meta strong { color: var(--pp-ink-2); font-weight: 500; }

/* Parties (first page only) */
.pp-parties { display: flex; margin-top: 18px; }
.pp-parties .party { flex: 1; padding-right: 24px; }
.pp-parties .label {
  font-family: "JetBrains Mono", ui-monospace, monospace;
  font-size: 9px; letter-spacing: 0.14em; text-transform: uppercase;
  color: var(--pp-muted); margin-bottom: 5px;
}
.pp-parties .pname {
  font-size: 16px; font-weight: 500; color: var(--pp-ink); margin-bottom: 2px;
}
.pp-parties .pline { font-size: 12px; color: var(--pp-ink-2); line-height: 1.5; }

/* ─── Section heads ───────────────────────────────────────── */
.pp-eyebrow {
  font-family: "JetBrains Mono", ui-monospace, monospace;
  font-size: 9.5px; letter-spacing: 0.16em; text-transform: uppercase;
  color: var(--pp-muted); margin: 0 0 6px;
}
.pp-h2 {
  font-family: "Newsreader", Georgia, serif;
  font-size: 18px; font-weight: 500; letter-spacing: -0.01em;
  color: var(--pp-ink); margin: 0 0 4px;
}
.pp-h3 {
  font-family: "Newsreader", Georgia, serif;
  font-size: 14px; font-weight: 600; letter-spacing: -0.005em;
  color: var(--pp-ink); margin: 0 0 6px;
}
.pp-lede {
  font-size: 11.5px; color: var(--pp-ink-2); line-height: 1.55;
  max-width: 64ch; margin: 0;
}
.pp-lede em { font-style: italic; color: var(--pp-ink); }
.pp-section { margin-top: 26px; }
.pp-section.tight { margin-top: 16px; }

/* ─── Pricing table (flex rows/cols — no <table>, no grid) ── */
.pp-table { display: flex; flex-direction: column; margin-top: 14px; }
.pp-thead {
  display: flex; align-items: flex-end;
  border-bottom: 1.5px solid var(--pp-strong);
  padding-bottom: 7px;
}
.pp-thead.continued { border-top: none; }
.pp-tbody { display: flex; flex-direction: column; }
.pp-tr {
  display: flex; align-items: baseline;
  padding: 9px 0;
  border-bottom: 1px solid var(--pp-rule);
}
.pp-tbody .pp-tr:last-child { border-bottom: 1.5px solid var(--pp-strong); }

/* columns */
.pp-c-prod { flex: 2.5 1 0; min-width: 0; padding-right: 14px; }
.pp-c-num  {
  flex: 1 1 0; min-width: 0; text-align: right;
  border-left: 1px solid transparent; border-right: 1px solid transparent;
  padding: 0 8px;
}
.pp-thead .pp-c-num { align-self: flex-end; }

/* recommended column — redundant signals that survive grayscale:
   bordered column box + tint + bold weight + ★/label in the header */
.pp-c-rec { border-left-color: var(--pp-rec-edge); border-right-color: var(--pp-rec-edge); background: var(--pp-rec-tint); }
.pp-thead .pp-c-rec { border-top: 1px solid var(--pp-rec-edge); padding-top: 5px; }
.pp-tbody .pp-tr:last-child .pp-c-rec { border-bottom: 1px solid var(--pp-rec-edge); }

/* header cell content */
.pp-th-lab {
  font-family: "JetBrains Mono", ui-monospace, monospace;
  font-size: 10px; letter-spacing: 0.06em; color: var(--pp-ink); font-weight: 500;
}
.pp-c-prod .pp-th-lab { letter-spacing: 0.12em; text-transform: uppercase; font-size: 9px; color: var(--pp-muted); }
.pp-th-sub {
  font-family: "JetBrains Mono", ui-monospace, monospace;
  font-size: 8.5px; letter-spacing: 0.04em; color: var(--pp-muted); margin-top: 3px; font-weight: 400;
}
.pp-th-rec {
  display: inline-flex; align-items: center; gap: 4px;
  color: var(--pp-ink);
}
.pp-th-rec .star { color: var(--pp-star); font-size: 10px; }
.pp-th-sub .rec-word { color: var(--pp-star); letter-spacing: 0.10em; }

/* body cells */
.pp-prod-name { font-size: 13px; font-weight: 500; color: var(--pp-ink); line-height: 1.25; }
.pp-prod-meta {
  font-family: "JetBrains Mono", ui-monospace, monospace;
  font-size: 9.5px; color: var(--pp-muted); letter-spacing: 0.02em; margin-top: 3px;
}
.pp-prod-meta .code { color: var(--pp-ink-3); }
.pp-prod-flat { font-style: italic; font-size: 10.5px; color: var(--pp-ink-3); margin-top: 3px; }
.pp-price {
  font-family: "JetBrains Mono", ui-monospace, monospace;
  font-size: 12.5px; color: var(--pp-ink); font-variant-numeric: tabular-nums;
}
.pp-c-rec .pp-price { font-weight: 600; }
.pp-price.dash { color: var(--pp-muted); }
.pp-price.req {
  font-family: "Newsreader", Georgia, serif; font-style: italic;
  font-size: 11px; color: var(--pp-muted); white-space: nowrap;
}
.pp-table-foot {
  font-family: "JetBrains Mono", ui-monospace, monospace;
  font-size: 9px; letter-spacing: 0.04em; color: var(--pp-muted);
  margin-top: 8px; display: flex; justify-content: space-between;
}

/* ─── Charges block (one-time fees + pass-through freight) ── */
.pp-charges { /* kept-together block (react-pdf wrap={false}) */ }
.pp-charge-sub { font-size: 10.5px; font-style: italic; color: var(--pp-ink-3); margin: 2px 0 8px; }
.pp-charge-group-label {
  font-family: "JetBrains Mono", ui-monospace, monospace;
  font-size: 8.5px; letter-spacing: 0.12em; text-transform: uppercase;
  color: var(--pp-muted); margin: 12px 0 2px;
}
.pp-charge-row {
  display: flex; align-items: baseline;
  padding: 8px 0; border-bottom: 1px solid var(--pp-rule);
}
.pp-charge-row .c-label { flex: 1; padding-right: 14px; }
.pp-charge-row .c-label .t { font-size: 12.5px; color: var(--pp-ink); }
.pp-charge-row .c-label .s { display: block; font-size: 10.5px; font-style: italic; color: var(--pp-muted); margin-top: 2px; line-height: 1.4; }
.pp-charge-row .c-qty {
  flex: 0 0 130px; text-align: right; padding-right: 16px;
  font-family: "JetBrains Mono", ui-monospace, monospace; font-size: 9.5px; color: var(--pp-ink-3); letter-spacing: 0.02em;
}
.pp-charge-row .c-amt {
  flex: 0 0 96px; text-align: right;
  font-family: "JetBrains Mono", ui-monospace, monospace; font-size: 12.5px; font-weight: 500; color: var(--pp-ink); font-variant-numeric: tabular-nums;
}
.pp-charge-row .c-amt .per { font-size: 9px; font-weight: 400; color: var(--pp-muted); margin-left: 2px; }

/* ─── Terms block (flex-wrap, no grid) ────────────────────── */
.pp-terms {
  display: flex; flex-wrap: wrap;
  border-top: 1.5px solid var(--pp-strong);
  padding-top: 16px; margin-top: 8px;
}
.pp-term { flex: 0 0 50%; padding: 0 24px 16px 0; }
.pp-term .label {
  font-family: "JetBrains Mono", ui-monospace, monospace;
  font-size: 9px; letter-spacing: 0.14em; text-transform: uppercase;
  color: var(--pp-muted); margin-bottom: 4px;
}
.pp-term .value { font-size: 12.5px; color: var(--pp-ink); line-height: 1.45; }

/* Notes callout */
.pp-notes {
  margin-top: 6px; padding: 12px 16px;
  background: oklch(0.97 0.010 90);
  border-left: 3px solid var(--pp-rule-2);
}
.pp-notes .label {
  font-family: "JetBrains Mono", ui-monospace, monospace;
  font-size: 9px; letter-spacing: 0.14em; text-transform: uppercase;
  color: var(--pp-muted); margin-bottom: 5px;
}
.pp-notes p { font-size: 11px; color: var(--pp-ink-2); line-height: 1.55; margin: 0; }

/* How-to-accept */
.pp-accept { margin-top: 22px; }
.pp-accept p { font-size: 11.5px; color: var(--pp-ink-2); line-height: 1.55; margin: 0; max-width: 64ch; }

/* ─── Running header (continuation pages — react-pdf fixed) ── */
.pp-runhead {
  position: absolute; top: 28px; left: 64px; right: 64px;
  display: flex; align-items: baseline; justify-content: space-between;
  padding-bottom: 8px; border-bottom: 1px solid var(--pp-rule);
  font-family: "JetBrains Mono", ui-monospace, monospace;
  font-size: 9px; letter-spacing: 0.06em; color: var(--pp-ink-3);
}
.pp-runhead .l { color: var(--pp-ink-2); }
.pp-runhead .l strong { color: var(--pp-ink); font-weight: 500; letter-spacing: 0.10em; text-transform: uppercase; }
.pp-runhead .r { text-transform: uppercase; letter-spacing: 0.10em; color: var(--pp-muted); }
.pp-sheet.continuation { padding-top: 64px; }

/* ─── Footer (every page — react-pdf fixed) ───────────────── */
.pp-footer {
  position: absolute; left: 64px; right: 64px; bottom: 30px;
  display: flex; align-items: baseline; justify-content: space-between;
  padding-top: 10px; border-top: 1px solid var(--pp-rule);
  font-family: "JetBrains Mono", ui-monospace, monospace;
  font-size: 8.5px; letter-spacing: 0.05em; color: var(--pp-muted);
}
.pp-footer .l strong { color: var(--pp-ink-3); font-weight: 500; letter-spacing: 0.10em; text-transform: uppercase; }

/* global React, NXCPDF */
// CD Commission — Customer-Facing PDF Render Layer
// The paged render of the locked customer-view tree (brief §1).
// Authored to react-pdf primitives (brief §3): flex-only composition,
// explicit page boxes, running header/footer as fixed elements, hard page splits.
// Boundary guard (brief §1): this tree reads ONLY customer-visible fields.

const { Fragment } = React;
const D = NXCPDF;

// ─── formatters ──────────────────────────────────────────
function money(n, { perUnit = false } = {}) {
  if (n == null) return "—";
  const dp = perUnit ? 2 : (Math.abs(n) >= 100 ? 0 : 2);
  return "$" + n.toLocaleString("en-US", { minimumFractionDigits: dp, maximumFractionDigits: dp });
}
function unit(n) { return n == null ? "—" : "$" + n.toFixed(2); }
function qtyK(n) { return n >= 1000 ? `${(n / 1000).toFixed(0)}k` : n.toLocaleString("en-US"); }
function longDate(s) {
  return new Date(s + "T00:00:00").toLocaleDateString("en-US", { month: "long", day: "numeric", year: "numeric" });
}

// ─── Masthead (first page only) ──────────────────────────
function Masthead({ vendor, quote }) {
  return (
    <div className="pp-masthead">
      <div className="v-id">
        <div className="v-name">{vendor.name}</div>
        <div className="v-sub">{vendor.sub}</div>
      </div>
      <div className="v-meta">
        <span className="qnum">{quote.quote_number}</span>
        <div><strong>Issued</strong> · {longDate(quote.issued_date)}</div>
        <div><strong>Valid until</strong> · {longDate(quote.valid_until)}</div>
      </div>
    </div>
  );
}

// ─── Parties (first page only) ───────────────────────────
function Parties({ vendor, customer }) {
  return (
    <div className="pp-parties">
      <div className="party">
        <div className="label">Prepared for</div>
        <div className="pname">{customer.name}</div>
        <div className="pline">{customer.contact} · {customer.role}</div>
        <div className="pline">{customer.email}</div>
        <div className="pline">{customer.address}</div>
      </div>
      <div className="party">
        <div className="label">Prepared by</div>
        <div className="pname">{vendor.name}</div>
        <div className="pline">{vendor.contact_name}</div>
        <div className="pline">{vendor.contact_email} · {vendor.contact_phone}</div>
        <div className="pline">{vendor.address}</div>
      </div>
    </div>
  );
}

// ─── Pricing table (flex; tier_table | single_tier; splittable) ──
function PricingTable({ skus, layout, continued = false }) {
  const { tiers, recommendedTierIdx } = D;
  const isSingle = layout === "single_tier";
  // columns + the tier-array index each maps to
  const cols = isSingle ? [{ tier: tiers[recommendedTierIdx], ti: recommendedTierIdx }]
                        : tiers.map((t, i) => ({ tier: t, ti: i }));

  return (
    <div className="pp-table">
      {continued && (
        <div className="pp-eyebrow" style={{ marginBottom: 8 }}>Tiered pricing · continued — {D.quote.quote_number}</div>
      )}

      <div className={"pp-thead" + (continued ? " continued" : "")}>
        <div className="pp-c-prod">
          <div className="pp-th-lab">Product</div>
        </div>
        {cols.map(({ tier, ti }) => {
          const rec = tier.recommended;
          return (
            <div key={tier.id} className={"pp-c-num" + (!isSingle && rec ? " pp-c-rec" : "")}>
              <div className="pp-th-lab">
                {isSingle ? (
                  <span>Unit price</span>
                ) : rec ? (
                  <span className="pp-th-rec"><span className="star">★</span>{tier.label}</span>
                ) : (
                  <span>{tier.label}</span>
                )}
              </div>
              <div className="pp-th-sub">
                {isSingle
                  ? <span>{tier.label} · {qtyK(tier.quantity)} units · <span className="rec-word">recommended</span></span>
                  : <span>{qtyK(tier.quantity)} units{rec ? <span className="rec-word"> · recommended</span> : null}</span>}
              </div>
            </div>
          );
        })}
      </div>

      <div className="pp-tbody">
        {skus.map(sku => {
          const isFlat = sku.shape === "flat";
          return (
            <div key={sku.id} className="pp-tr">
              <div className="pp-c-prod">
                <div className="pp-prod-name">{sku.name}</div>
                <div className="pp-prod-meta"><span className="code">{sku.code}</span> · {sku.pack}</div>
                {isFlat && <div className="pp-prod-flat">Flat across all volume tiers</div>}
              </div>
              {cols.map(({ tier, ti }) => {
                const p = sku.tier_prices[ti];
                const rec = !isSingle && tier.recommended;
                let cell;
                if (p == null) {
                  cell = <span className="pp-price req">quote on request</span>;
                } else if (isFlat && !isSingle && ti !== 0) {
                  cell = <span className="pp-price dash">—</span>;
                } else {
                  cell = <span className="pp-price">{unit(p)}</span>;
                }
                return <div key={tier.id} className={"pp-c-num" + (rec ? " pp-c-rec" : "")}>{cell}</div>;
              })}
            </div>
          );
        })}
      </div>
    </div>
  );
}

function PricingFoot({ partial = false }) {
  return (
    <div className="pp-table-foot">
      <span>Per-unit pricing, in USD. ★ T2 is our recommended first-PO tier.</span>
      {partial && <span>quote on request — pricing finalizes once the noted milestone clears.</span>}
    </div>
  );
}

// ─── Charges block (one-time fees + pass-through freight) ──
function ChargesBlock({ tiers, recommendedTierIdx }) {
  const { service_fees, freight_lines } = D;
  const recTier = tiers[recommendedTierIdx];
  return (
    <div className="pp-charges">
      <div className="pp-eyebrow">Additional charges</div>
      <div className="pp-h2">One-time fees &amp; pass-through freight</div>
      <div className="pp-charge-sub">
        Freight amounts shown landed per unit for {recTier.full} ({qtyK(recTier.quantity)} units). Per-tier amounts available on request.
      </div>

      <div className="pp-charge-group-label">Project &amp; SKU fees · one-time</div>
      {service_fees.map(sf => (
        <div className="pp-charge-row" key={sf.id}>
          <div className="c-label"><span className="t">{sf.label}</span><span className="s">{sf.sub}</span></div>
          <div className="c-qty">{sf.qty_label}</div>
          <div className="c-amt">{money(sf.amount)}</div>
        </div>
      ))}

      <div className="pp-charge-group-label">Pass-through freight · billed at cost</div>
      {freight_lines.map(fl => (
        <div className="pp-charge-row" key={fl.id}>
          <div className="c-label"><span className="t">{fl.label}</span><span className="s">{fl.sub}</span></div>
          <div className="c-qty">{fl.qty_label}</div>
          <div className="c-amt">{unit(fl.tier_amounts[recommendedTierIdx])}<span className="per">/unit</span></div>
        </div>
      ))}
    </div>
  );
}

// ─── Commercial terms ────────────────────────────────────
function TermsBlock({ quote, incoterms }) {
  return (
    <div className="pp-terms">
      <div className="pp-term"><div className="label">Valid until</div><div className="value">{longDate(quote.valid_until)}</div></div>
      <div className="pp-term"><div className="label">Payment terms</div><div className="value">{quote.payment_terms}</div></div>
      <div className="pp-term"><div className="label">Lead time</div><div className="value">{quote.lead_time}</div></div>
      <div className="pp-term"><div className="label">Incoterms</div><div className="value">{incoterms}</div></div>
    </div>
  );
}

function NotesBlock({ notes }) {
  if (!notes) return null;
  return (
    <div className="pp-notes"><div className="label">Notes</div><p>{notes}</p></div>
  );
}

function HowToAccept() {
  return (
    <div className="pp-accept">
      <div className="pp-h3">How to accept</div>
      <p>Reply to this quote with the tier and quantity you'd like to proceed on. We'll issue a PO confirmation and production schedule within 2 business days of acceptance.</p>
    </div>
  );
}

// ─── Running elements ────────────────────────────────────
function RunHead({ vendor, quote }) {
  return (
    <div className="pp-runhead">
      <div className="l"><strong>{vendor.name}</strong> · {quote.quote_number}</div>
      <div className="r">Quotation · continued</div>
    </div>
  );
}
function Footer({ vendor, quote, page, pages }) {
  return (
    <div className="pp-footer">
      <div className="l"><strong>{vendor.name}</strong> · {quote.quote_number}</div>
      <div className="r">Page {page} of {pages}</div>
    </div>
  );
}

// ─── Page wrapper ────────────────────────────────────────
function Sheet({ children, footer, runhead = null, continuation = false }) {
  return (
    <div className={"pp-sheet" + (continuation ? " continuation" : "")}>
      {runhead}
      <div className="pp-flow">{children}</div>
      {footer}
    </div>
  );
}

function Break({ label }) { return <div className="cpdf-break">{label}</div>; }

// ═══ State A · Pure tier-pricing (single page) ═══════════
function StatePure({ layout }) {
  const { vendor, customer, quote, skuSets, skus, tiers, recommendedTierIdx } = D;
  const set = skuSets.pure.map(id => skus.find(s => s.id === id));
  const isSingle = layout === "single_tier";
  return (
    <Sheet footer={<Footer vendor={vendor} quote={quote} page={1} pages={1} />}>
      <Masthead vendor={vendor} quote={quote} />
      <Parties vendor={vendor} customer={customer} />
      <div className="pp-section">
        <div className="pp-eyebrow">{isSingle ? "Confirmed pricing" : "Tiered pricing"}</div>
        <div className="pp-h2">{isSingle ? `Per-unit pricing · ${tiers[recommendedTierIdx].full}` : "Per-unit pricing across volume tiers"}</div>
        <p className="pp-lede">
          Pricing landed <em>FOB Long Beach</em> — container freight, duty, and applicable tariffs are included in the unit price shown.
          {isSingle ? " Full volume tier-pricing available on request." : " Tier 2 is recommended for first-PO production runs."}
        </p>
        <PricingTable skus={set} layout={layout} />
        <PricingFoot />
      </div>
      <div className="pp-section">
        <TermsBlock quote={quote} incoterms={quote.incoterms_bundled} />
        <NotesBlock notes={quote.customer_facing_notes} />
        <HowToAccept />
      </div>
    </Sheet>
  );
}

// ═══ State B · Pass-through freight + visible fees (2 pages) ═══
function StatePassThrough({ layout }) {
  const { vendor, customer, quote, skuSets, skus, tiers, recommendedTierIdx } = D;
  const set = skuSets.passThrough.map(id => skus.find(s => s.id === id));
  return (
    <Fragment>
      <Sheet footer={<Footer vendor={vendor} quote={quote} page={1} pages={2} />}>
        <Masthead vendor={vendor} quote={quote} />
        <Parties vendor={vendor} customer={customer} />
        <div className="pp-section">
          <div className="pp-eyebrow">Tiered pricing</div>
          <div className="pp-h2">Per-unit pricing across volume tiers</div>
          <p className="pp-lede">
            Pricing landed <em>EXW Long Beach</em>. Outbound freight is billed separately at cost; one-time charges are itemized below. See page 2 for commercial terms.
          </p>
          <PricingTable skus={set} layout={layout} />
          <PricingFoot />
        </div>
        <div className="pp-section">
          <ChargesBlock tiers={tiers} recommendedTierIdx={recommendedTierIdx} />
        </div>
      </Sheet>

      <Break label="page break · 1 → 2" />

      <Sheet
        continuation
        runhead={<RunHead vendor={vendor} quote={quote} />}
        footer={<Footer vendor={vendor} quote={quote} page={2} pages={2} />}
      >
        <div className="pp-section tight">
          <div className="pp-eyebrow">Commercial terms</div>
          <div className="pp-h2">Terms &amp; acceptance</div>
          <TermsBlock quote={quote} incoterms={quote.incoterms_passthrough} />
          <NotesBlock notes={quote.customer_facing_notes} />
          <HowToAccept />
        </div>
      </Sheet>
    </Fragment>
  );
}

// ═══ State C · Partial completeness + table overflow (2 pages) ═══
function StatePartial({ layout }) {
  const { vendor, customer, quote, skuSets, skus, tiers, recommendedTierIdx } = D;
  const set = skuSets.partial.map(id => skus.find(s => s.id === id));
  const pageOne = set.slice(0, 4);
  const pageTwo = set.slice(4);
  return (
    <Fragment>
      <Sheet footer={<Footer vendor={vendor} quote={quote} page={1} pages={2} />}>
        <Masthead vendor={vendor} quote={quote} />
        <Parties vendor={vendor} customer={customer} />
        <div className="pp-section">
          <div className="pp-eyebrow">Tiered pricing</div>
          <div className="pp-h2">Per-unit pricing across volume tiers</div>
          <p className="pp-lede">
            Pricing landed <em>FOB Long Beach</em>. <em>Glow Capsule (CAP-60)</em> Tier 1 pricing is pending finalization of the formulation R&amp;D milestone — a quote is available on request once raw-ingredient sourcing is locked.
          </p>
          <PricingTable skus={pageOne} layout={layout} />
        </div>
      </Sheet>

      <Break label="page break · 1 → 2 · table continues" />

      <Sheet
        continuation
        runhead={<RunHead vendor={vendor} quote={quote} />}
        footer={<Footer vendor={vendor} quote={quote} page={2} pages={2} />}
      >
        <div className="pp-section tight">
          <PricingTable skus={pageTwo} layout={layout} continued />
          <PricingFoot partial />
        </div>
        <div className="pp-section">
          <TermsBlock quote={quote} incoterms={quote.incoterms_bundled} />
          <NotesBlock notes={quote.customer_facing_notes} />
          <HowToAccept />
        </div>
      </Sheet>
    </Fragment>
  );
}

// ─── Host (preview chrome — NOT part of the PDF) ─────────
const STATES = [
  { id: "pure",        n: "①", label: "Pure tier-pricing" },
  { id: "passThrough", n: "②", label: "Pass-through + fees" },
  { id: "partial",     n: "③", label: "Partial + overflow" },
];

function CustomerPdfHost({ state, setState, layout, setLayout }) {
  const Variant = ({ pure: StatePure, passThrough: StatePassThrough, partial: StatePartial })[state] || StatePure;
  return (
    <div className="cpdf-stage">
      <div className="cpdf-toolbar">
        <div className="grp">
          <span className="ribbon">PDF render · this is the customer artifact</span>
          <div className="seg">
            {STATES.map(s => (
              <button key={s.id} className={state === s.id ? "active" : ""} onClick={() => setState(s.id)}>
                {s.n} {s.label}
              </button>
            ))}
          </div>
        </div>
        <div className="grp">
          <span className="layout-toggle">
            <span style={{ color: "var(--ink-4)", fontFamily: "var(--mono)", fontSize: 10, letterSpacing: "0.06em", textTransform: "uppercase" }}>Layout:</span>
            <button className={layout === "tier_table" ? "active" : ""} onClick={() => setLayout("tier_table")}>tier table</button>
            <span className="bar">|</span>
            <button className={layout === "single_tier" ? "active" : ""} onClick={() => setLayout("single_tier")}>single tier</button>
          </span>
          <div className="cpdf-dl">
            <button className="btn sm">⤓ Download PDF</button>
          </div>
        </div>
      </div>

      <div className="cpdf-dn">
        <div className="eyebrow">CD · paged render layer</div>
        <strong>This is the paged layer, not the web preview.</strong> Authored within paged-PDF primitives — flex composition only, no CSS grid, US-Letter page boxes, running header/footer as <code>fixed</code> elements. Page breaks are hard-split here to show the treatment; production breaks automatically. Boundary guard holds: this tree reads only customer-visible fields — no margin, markup, cost, supplier, duty, CBM, version, or scenario.
      </div>

      <Variant layout={layout} />
    </div>
  );
}

Object.assign(window, {
  CustomerPdfHost,
  StatePure, StatePassThrough, StatePartial,
  PricingTable, ChargesBlock, TermsBlock,
});

