.pp-tk-total {
  font-family: "Newsreader", Georgia, serif;
  font-size: 24px; font-weight: 500; letter-spacing: -0.02em; color: var(--pp-ink);
  margin-top: 14px; font-variant-numeric: tabular-nums; line-height: 1.05;
}
.pp-tk-card.rec .pp-tk-total { font-weight: 600; }
.pp-tk-total .from { font-family: "Newsreader", Georgia, serif; font-style: italic; font-size: 12px; font-weight: 400; color: var(--pp-muted); display: block; }
.pp-tk-total.req { font-size: 15px; font-style: italic; font-weight: 500; color: var(--pp-ink-2); }

/* single_tier turnkey-only → one hero figure */
.pp-tk-hero {
  display: flex; align-items: baseline; justify-content: space-between;
  border-top: 1.5px solid var(--pp-strong); border-bottom: 1.5px solid var(--pp-strong);
  padding: 20px 0; margin: 4px 0 0;
}
.pp-tk-hero .h-meta { }
.pp-tk-hero .h-label {
  font-family: "JetBrains Mono", ui-monospace, monospace;
  font-size: 9px; letter-spacing: 0.14em; text-transform: uppercase; color: var(--pp-muted); margin-bottom: 6px;
}
.pp-tk-hero .h-tier { font-family: "Newsreader", Georgia, serif; font-size: 16px; color: var(--pp-ink); }
.pp-tk-hero .h-tier .star { color: var(--pp-star); }
.pp-tk-hero .h-qty { font-family: "JetBrains Mono", ui-monospace, monospace; font-size: 10px; color: var(--pp-ink-3); margin-top: 3px; letter-spacing: 0.03em; }
.pp-tk-hero .h-num {
  font-family: "Newsreader", Georgia, serif;
  font-size: 40px; font-weight: 600; letter-spacing: -0.03em; color: var(--pp-ink);
  font-variant-numeric: tabular-nums; line-height: 1;
}
.pp-tk-hero .h-num.req { font-size: 24px; font-style: italic; font-weight: 500; color: var(--pp-ink-2); }

/* what's-included block (Q3 — fills the vacated space) */
.pp-tk-included {
  margin-top: 20px; padding: 14px 18px;
  background: oklch(0.975 0.008 90);
  border: 1px solid var(--pp-rule);
}
.pp-tk-included .label {
  font-family: "JetBrains Mono", ui-monospace, monospace;
  font-size: 9px; letter-spacing: 0.14em; text-transform: uppercase; color: var(--pp-muted); margin-bottom: 8px;
}
.pp-tk-scope { font-size: 12px; color: var(--pp-ink); line-height: 1.5; }
.pp-tk-scope .code { font-family: "JetBrains Mono", ui-monospace, monospace; font-size: 10.5px; color: var(--pp-ink-3); }
.pp-tk-incl-list { margin-top: 10px; display: flex; flex-direction: column; gap: 5px; }
.pp-tk-incl {
  font-family: "Newsreader", Georgia, serif; font-size: 11px; color: var(--pp-ink-2); line-height: 1.4;
  display: flex; gap: 8px;
}
.pp-tk-incl .tick { color: var(--pp-ink-3); flex-shrink: 0; }
.pp-tk-incl.out .tick { color: var(--pp-muted); }
.pp-tk-incl.out { color: var(--pp-ink-3); font-style: italic; }

