.r9-so-lrow.onetime .desc .n { font-weight: 400; }
.r9-so-lrow.onetime .desc .s {
  font-size: 11px; font-style: italic; color: var(--ink-4); margin-top: 2px; line-height: 1.4;
}

/* Totals ladder */
.r9-so-totals { padding: 4px 20px 16px; }
.r9-so-trow {
  display: flex; justify-content: flex-end; align-items: baseline; gap: 18px;
  padding: 6px 0;
}
.r9-so-trow .k {
  font-family: var(--mono); font-size: 10px; letter-spacing: 0.07em;
  text-transform: uppercase; color: var(--ink-3);
}
.r9-so-trow .v {
  font-family: var(--mono); font-size: 13px; color: var(--ink-2);
  min-width: 104px; text-align: right; font-variant-numeric: tabular-nums;
}
.r9-so-trow.grand { border-top: 1.5px solid var(--ink); margin-top: 6px; padding-top: 11px; }
.r9-so-trow.grand .k { color: var(--ink); font-size: 10.5px; }
.r9-so-trow.grand .v {
  font-family: var(--display); font-size: 25px; font-weight: 500;
  color: var(--ink); letter-spacing: -0.018em;
}

/* Status ledger — the "not yet" strip. Position fixed across all three states. */
.r9-so-status { border-top: 1px solid var(--rule); background: var(--paper-2); }
.r9-so-srow {
  display: flex; align-items: center; gap: 12px;
  padding: 11px 20px; border-top: 1px solid var(--rule);
}
.r9-so-srow:first-child { border-top: none; }
.r9-so-srow .icon {
  flex: 0 0 18px; height: 18px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: 10px; font-weight: 600;
  background: var(--paper-3); color: var(--ink-4); border: 1px dashed var(--rule-2);
}
.r9-so-srow.done .icon { background: var(--good); color: var(--paper); border: none; }
.r9-so-srow.fail .icon { background: var(--bad);  color: var(--paper); border: none; }
.r9-so-srow .lbl { flex: 1; font-size: 12.5px; color: var(--ink-2); line-height: 1.45; }
.r9-so-srow .lbl strong { color: var(--ink); }
.r9-so-srow .val {
  font-family: var(--mono); font-size: 10px; letter-spacing: 0.06em;
  text-transform: uppercase; color: var(--ink-4); text-align: right; flex-shrink: 0;
}
.r9-so-srow.done .val { color: var(--good); }
.r9-so-srow.fail .val { color: var(--bad); }

/* Pre-send flags */
.r9-so-flag {
  display: flex; align-items: flex-start; gap: 11px;
  padding: 12px 20px; border-top: 1px solid var(--rule);
}
.r9-so-flag.warn { background: var(--warn-soft); }
.r9-so-flag.bad  { background: var(--bad-soft); }
.r9-so-flag .g { flex: 0 0 16px; font-family: var(--mono); font-size: 12px; margin-top: 1px; }
.r9-so-flag.warn .g { color: var(--warn); }
.r9-so-flag.bad  .g { color: var(--bad); }
.r9-so-flag .t { font-size: 12.5px; color: var(--ink); font-weight: 500; }
.r9-so-flag .s { font-size: 11.5px; color: var(--ink-2); line-height: 1.5; margin-top: 2px; }

/* Failed state — the two-facts banner. Deal closed AND order not placed.
   Deliberately NOT a full-bleed red catastrophe: the left half is still true.
                                                                 ← LOAD-BEARING */
.r9-so-split {
  display: flex; flex-wrap: wrap; gap: 0;
  border: 1px solid oklch(from var(--bad) l c h / 0.4); border-radius: 8px;
  overflow: hidden; margin-bottom: 14px;
}
.r9-so-split .half { flex: 1 1 260px; padding: 15px 18px; }
.r9-so-split .half.held { background: var(--good-soft); }
.r9-so-split .half.lost { background: var(--bad-soft); border-left: 1px solid oklch(from var(--bad) l c h / 0.3); }
.r9-so-split .half .k {
  display: flex; align-items: center; gap: 7px;
  font-family: var(--mono); font-size: 9px; letter-spacing: 0.11em;
  text-transform: uppercase; margin-bottom: 6px;
}
.r9-so-split .half.held .k { color: var(--good); }
.r9-so-split .half.lost .k { color: var(--bad); }
.r9-so-split .half .t {
  font-family: var(--display); font-size: 15.5px; font-weight: 500;
  color: var(--ink); letter-spacing: -0.008em; margin-bottom: 4px;
}
.r9-so-split .half .s { font-size: 12px; color: var(--ink-2); line-height: 1.55; }
.r9-so-split .half .s code { font-family: var(--mono); font-size: 11px; }
.r9-so-split .half .acts { display: flex; gap: 8px; margin-top: 11px; flex-wrap: wrap; }
.r9-so-split .half .err {
  font-family: var(--mono); font-size: 10px; letter-spacing: 0.03em;
  color: oklch(from var(--bad) calc(l - 0.06) c h); margin-top: 7px; line-height: 1.5;
}

/* ─── Narrow / stacked · receipt ─────────────────────────── */
.r8-shell.narrow .r9-so-lrow { grid-template-columns: minmax(0, 1fr) 96px; row-gap: 4px; }
.r8-shell.narrow .r9-so-lrow.head { display: none; }
.r8-shell.narrow .r9-so-lrow .num.qty,
.r8-shell.narrow .r9-so-lrow .num.unit { grid-column: 1; text-align: left; font-size: 10.5px; color: var(--ink-4); }
.r8-shell.narrow .r9-so-meta { grid-template-columns: minmax(0, 1fr); }
.r8-shell.narrow .r9-so-meta .cell { border-left: none; border-top: 1px solid var(--rule); }
.r8-shell.narrow .r9-so-meta .cell:first-child { border-top: none; }
@media (max-width: 900px) {
  .r9-so-lrow { grid-template-columns: minmax(0, 1fr) 96px; row-gap: 4px; }
  .r9-so-lrow.head { display: none; }
  .r9-so-lrow .num.qty, .r9-so-lrow .num.unit { grid-column: 1; text-align: left; font-size: 10.5px; color: var(--ink-4); }
  .r9-so-meta { grid-template-columns: minmax(0, 1fr); }
  .r9-so-meta .cell { border-left: none; border-top: 1px solid var(--rule); }
  .r9-so-meta .cell:first-child { border-top: none; }
  .r9-so-trow .v { min-width: 88px; }
}

